// Generated by `xark client` from `schema.json`: a typed client for the `cube` circuit.
//
//   #[circuit]
//   fn cube(secret: Private<Field>, result: Public<Field>)
//
// `xark build` records the circuit's parameter types in target/xark/cube/schema.json
// and `xark client` turns them into the types below. Don't edit this file: change
// the circuit, then rebuild and rerun `xark client`. Values go in their natural
// forms (dates, strings, variant names, bytes); xark-wasm encodes them against the
// schema, `cube.schema.json` (written with this file), exactly as `xark prove --inputs`
// does.

import { CheckFailed, Circuit, Field, InputError, type Json, type Proof, type Prover, type Verifier } from "@blueshift-gg/xark-wasm/client";
import schema from "./cube.schema.json" with { type: "json" };
export { CheckFailed, Field, InputError };

/** Every input of `cube`. */
export interface CubeInputs {
  secret: Field | bigint | number | string;
  result: Field | bigint | number | string;
}

/** The public inputs: what a verifier supplies, and what a proof reveals. */
export interface CubePublicInputs {
  result: Field | bigint | number | string;
}

/** The public inputs, decoded from a proof. */
export interface CubePublicValues {
  result: Field;
}

/**
 * `cube`: make a prover or verifier from a URL serving a copy of
 * `target/xark/cube/` (relative to the page in a browser) or from the bytes:
 *
 * ```ts
 * const prover = await Cube.prover("/circuits/cube/");
 * const proof = prover.prove(inputs);
 * send(proof.toBytes());
 * const verifier = await Cube.verifier(vkBytes);
 * verifier.verify(proof.toBytes()); // true
 * ```
 */
export const Cube = new Circuit<CubeInputs, CubePublicInputs, CubePublicValues, {}>({
  name: "cube",
  schema,
  decodePublic,
  client: false,
});

export type CubeProver = Prover<CubeInputs, CubePublicInputs, CubePublicValues, {}>;
export type CubeVerifier = Verifier<CubePublicInputs, CubePublicValues, {}>;
export type CubeProof = Proof<CubePublicValues>;

function decodePublic(v: Json<CubePublicValues>): CubePublicValues {
  return {
    result: new Field(v.result),
  };
}
